import json,re,html
d=json.load(open('products/services/r-data-repair/raw/posit-search-paid.json'))
ts={t['id']:t for t in d.get('topics',[])}
for p in d.get('posts',[])[:25]:
  t=ts.get(p['topic_id'],{})
  print(p['topic_id'],p['created_at'][:10],t.get('category_id'),t.get('closed'),'|',t.get('title'),'|',p.get('blurb','')[:200].replace('\n',' '))
h=open('products/services/r-data-repair/raw/posit-faq.html').read()
tx=html.unescape(re.sub(r'<[^>]+>',' ',h))
tx=re.sub(r'\s+',' ',tx)
for k in ['job','hire','paid','commercial','advertis','spam','AI','generat','LLM','ChatGPT','homework']:
  for m in re.finditer(k,tx):
    print('FAQ',k,'::',tx[max(0,m.start()-120):m.start()+160]); break
